// План specs/pricebook.md 2.2 (кейс .qa/tests/pricebook/PB-05). Pre-Prod, preprod-ttp (TTP Test Locks), десктоп, EN.
// @writes @data: черновик счёта «QA-AUTO pb-pick-inv #df9bec …» (сохраняется при добавлении позиции) — Delete в конце.
// Предусловие: в Price Book TTP Test Locks есть хотя бы одна позиция.
import { test, expect } from '../../fixtures';
import {
  ROLE, itemRow, openNewInvoice, openPriceBook, pickFirstFromPriceBook, priceBookTotal, removeDocumentAt, removeFromList, setInvoiceName, stamp,
} from './pricebook-helpers';

test.describe('Price Book — выбор позиции в документ (#df9bec)', () => {
  test('QA-AUTO: existing Price Book item is added to a new invoice via Select items → Select #df9bec @desktop @writes @data', async ({ asUser }) => {
    test.setTimeout(120_000);
    const page = await asUser(ROLE);
    const title = `QA-AUTO pb-pick-inv #df9bec ${stamp()}`;
    let invoiceUrl: string | null = null;
    try {
      await openPriceBook(page);
      const before = await priceBookTotal(page);

      // Шаги 1–3: New Invoice → Price Book → первая позиция → Select
      await openNewInvoice(page);
      await setInvoiceName(page, title);
      const name = await pickFirstFromPriceBook(page, 'Select');
      await expect(itemRow(page, name), `позиция «${name}» в Items счёта`).toHaveCount(1);
      invoiceUrl = page.url();

      await openPriceBook(page);
      expect(await priceBookTotal(page), 'Total Items не изменилось').toBe(before);
    } finally {
      await removeDocumentAt(page, invoiceUrl, title);
      await removeFromList(page, '/invoices', title);
    }
  });
});
